"""Human visual transcription. row=None means not defensibly readable.
Tuple format: section, row, displayed USD, optional note.
Map markers are observations, not inventory units or executed transactions.
"""
DATA = {}
def add(image_id, records):
    DATA[image_id] = records

def sg(image_id, grouped):
    records=[]
    for section, prices in grouped:
        for price in prices:
            records.append((section,None,price,'SeatGeek row numbers not printed in supplied map crop'))
    add(image_id,records)

